import assert from 'node:assert/strict';
import { existsSync, linkSync, mkdtempSync, readFileSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
import { inspectRom } from '../modretro.mjs';
import { main, prepareRomCopy } from '../prepare-rom.mjs';

// Generated bytes only; no game ROMs or vendor CLI/device are used by these tests.
function fixture(t, { revision = 0, zeroHeaderChecksum = false } = {}) {
  const dir = mkdtempSync(join(tmpdir(), 'modretro-copy-test-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const source = join(dir, 'Original with spaces.GBC');
  const output = join(dir, 'Nested', 'Copy with spaces.GBC');
  const data = Buffer.from(Array.from({ length: 32768 }, (_, index) => (index * 37 + 19) & 255));
  data.fill(0, 0x134, 0x150);
  data.write('COPY TEST', 0x134); data[0x143] = 0x80; data[0x14c] = revision;
  const headerChecksum = () => (-data.subarray(0x134, 0x14d).reduce((sum, byte) => sum + byte, 0) - 25) & 255;
  if (zeroHeaderChecksum) data[0x144] = headerChecksum();
  data[0x14d] = headerChecksum();
  data.writeUInt16BE(data.reduce((sum, byte) => sum + byte, 0) & 65535, 0x14e);
  writeFileSync(source, data);
  return { dir, source, output, data };
}

test('copy preserves original and all non-metadata bytes, with a verifiable manifest', t => {
  const { source, output, data } = fixture(t);
  const before = inspectRom(source);
  const manifest = prepareRomCopy(source, { output });
  const copy = readFileSync(output);
  assert.deepEqual(readFileSync(source), data);
  assert.deepEqual(copy.subarray(0, 0x14c), data.subarray(0, 0x14c));
  assert.deepEqual(copy.subarray(0x150), data.subarray(0x150));
  assert.equal(copy.length, data.length);
  assert.equal(copy[0x14c], 1);
  assert.equal(copy[0x14d], data[0x14d] - 1);
  assert.deepEqual(manifest.changes.map(change => change.offset), [0x14c, 0x14d]);
  assert.notEqual(manifest.source.sha256, manifest.copy.sha256);
  assert.notEqual(manifest.source.sha1, manifest.copy.sha1);
  assert.deepEqual(manifest.copy.requirements, before.requirements);
  assert.equal(inspectRom(output).global_checksum_valid, true);
  assert.deepEqual(JSON.parse(readFileSync(`${output}.json`, 'utf8')), manifest);
});

for (const [name, options, globalDelta] of [
  ['header checksum wraps from zero', { zeroHeaderChecksum: true }, 256],
  ['revision wraps from 255', { revision: 255 }, -256],
]) test(`${name} keeps both checksums valid without payload changes`, t => {
  const { source, output, data } = fixture(t, options);
  const manifest = prepareRomCopy(source, { output });
  const copy = readFileSync(output);
  assert.equal(copy[0x14c], options.revision === 255 ? 0 : 1);
  assert.equal(copy[0x14d], (data[0x14d] - 1) & 255);
  assert.equal(manifest.copy.global_checksum, (manifest.source.global_checksum + globalDelta) & 65535);
  assert.equal(inspectRom(output).global_checksum_valid, true);
  assert.deepEqual(copy.subarray(0, 0x14c), data.subarray(0, 0x14c));
  assert.deepEqual(copy.subarray(0x150), data.subarray(0x150));
});

test('preparing the same original twice produces identical copies', t => {
  const { source, output, dir } = fixture(t);
  const first = prepareRomCopy(source, { output });
  const second = prepareRomCopy(source, { output: join(dir, 'Second.gbc') });
  assert.equal(first.copy.sha256, second.copy.sha256);
  assert.deepEqual(readFileSync(first.copy.path), readFileSync(second.copy.path));
});

for (const kind of ['source', 'existing output', 'symlink', 'hardlink']) {
  test(`${kind} cannot be overwritten`, t => {
    const { source, output: freshOutput, dir, data } = fixture(t);
    let output = freshOutput;
    if (kind === 'source') output = source;
    else {
      output = join(dir, 'Existing.gbc');
      if (kind === 'existing output') writeFileSync(output, 'keep existing file');
      if (kind === 'symlink') symlinkSync(source, output);
      if (kind === 'hardlink') linkSync(source, output);
    }
    assert.throws(() => prepareRomCopy(source, { output }), /EEXIST/);
    assert.deepEqual(readFileSync(source), data);
    assert.equal(existsSync(`${output}.json`), false);
    if (kind === 'existing output') assert.equal(readFileSync(output, 'utf8'), 'keep existing file');
  });
}

test('existing manifest is preserved and incomplete output is removed', t => {
  const { source, dir, data } = fixture(t);
  const output = join(dir, 'Copy.gbc');
  writeFileSync(`${output}.json`, 'keep existing manifest');
  assert.throws(() => prepareRomCopy(source, { output }), /EEXIST/);
  assert.equal(existsSync(output), false);
  assert.equal(readFileSync(`${output}.json`, 'utf8'), 'keep existing manifest');
  assert.deepEqual(readFileSync(source), data);
});

for (const [name, offset, error] of [
  ['payload corruption', 0x200, /whole-ROM checksum/],
  ['header corruption', 0x134, /header checksum/],
]) test(`${name} is rejected rather than silently repaired`, t => {
  const { source, output, data } = fixture(t);
  data[offset] ^= 1; writeFileSync(source, data);
  assert.throws(() => prepareRomCopy(source, { output }), error);
  assert.deepEqual(readFileSync(source), data);
  assert.equal(existsSync(output), false);
  assert.equal(existsSync(`${output}.json`), false);
});

test('output extension is validated before creating files', t => {
  const { source, dir } = fixture(t);
  const output = join(dir, 'copy.zip');
  assert.throws(() => prepareRomCopy(source, { output }), /Output must/);
  assert.equal(existsSync(output), false);
});

test('command handles quoted paths and JSON output without a CLI dependency', t => {
  const { source, output } = fixture(t);
  const messages = [];
  assert.equal(main([source, '--output', output, '--json'], { print: message => messages.push(message) }), 0);
  assert.equal(JSON.parse(messages[0]).copy.path, realpathSync(output));
  assert.equal(JSON.parse(messages[0]).hardware, 'not_accessed');
});

test('help and invalid arguments never create a ROM', () => {
  const messages = [];
  assert.equal(main(['--help'], { print: message => messages.push(message) }), 0);
  assert.match(messages[0], /Never overwrites/);
  assert.throws(() => main([]), /exactly one/);
  assert.throws(() => main(['a.gbc', 'b.gbc']), /exactly one/);
  assert.throws(() => main(['a.gbc', '--force']), /Unknown option/);
});
